#!/usr/bin/env python3
"""The check for lint-all/t2. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev lint passes", *ws.dev("lint"))
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom tally.dates import business_days_between\nassert business_days_between(d.date(2024, 3, 1), d.date(2024, 3, 8)) == 5\nassert business_days_between(d.date(2024, 3, 2), d.date(2024, 3, 4)) == 0', env=None))


if __name__ == "__main__":
    main(check)
